gapF(){return"\u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f"},
gapo(){return"\u0645\u062a\u0648\u0633\u0637 \u0632\u0645\u0646 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f"},
gapd(){return"\u0646\u0633\u0628\u0629 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f"},
gaq1(){return"\u062d\u062c\u0645 \u0627\u0644\u0637\u0644\u0628\u0627\u062a \u062d\u0633\u0628 \u0627\u0644\u0646\u0648\u0639"},
gapN(){return"\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u062d\u0627\u0644\u0627\u062a"},
gapI(){return"\u0627\u0644\u0637\u0644\u0628\u0627\u062a \u062d\u0633\u0628 \u0627\u0644\u0625\u062f\u0627\u0631\u0629"},
gapp(){return"\u0645\u062a\u0648\u0633\u0637 \u0627\u0644\u0632\u0645\u0646 \u0644\u0643\u0644 \u0645\u0631\u062d\u0644\u0629"},
gapH(){return"\u0627\u0644\u0645\u0639\u0644\u0651\u0642\u0629 \u062d\u0633\u0628 \u0627\u0644\u0645\u0639\u062a\u0645\u062f \u0648\u0627\u0644\u0646\u0648\u0639"},
gapD(){return"\u0623\u0642\u062f\u0645 \u0627\u0644\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0651\u0642\u0629"},
gapC(){return"\u062a\u0648\u0632\u064a\u0639 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0625\u062c\u0627\u0632\u0627\u062a"},
gapB(){return"\u0623\u064a\u0627\u0645 \u0627\u0644\u0625\u062c\u0627\u0632\u0627\u062a (\u0627\u0644\u0645\u0648\u0633\u0645\u064a\u0629)"},
gapb(){return"\u0627\u0644\u0633\u0644\u0641 \u0627\u0644\u0645\u0635\u0631\u0648\u0641\u0629"},
